-- =============================================================================
-- 023_demo_bookings.sql
-- Zusty demo seed: the booking lifecycle (the heart of the marketplace).
--
-- Seeds:
--   bookings                 ids 401-480  (80 rows, every status covered)
--   booking_offers           ids 1-28   (counter-offer threads)
--   booking_deliverables     ids 1-69   (submitted / approved / revision rows)
--   booking_status_history   ids 1-383  (full transition trail for all 80)
--
-- Depends on: users (brands 1001-1020, creators 2001-2045), creators (101-145),
--             campaigns (301-330, linked by a guarded UPDATE at the bottom),
--             creator_packages (1101-1300, also linked by a guarded UPDATE).
--
-- Money model (consistent, so payments/invoices can be matched 1:1):
--   commission_amount = 15% of amount   (platform cut, deducted from the creator)
--   creator_earning   = amount - commission_amount
--   tax_amount        = 18% GST of amount
--   platform_fee      = 0.00, discount_amount = 0.00
--   total_amount      = amount + tax_amount   (== amount + platform_fee + tax_amount)
--   Booking 452 (the store-screenshot booking, delivered and awaiting the
--   brand's approval) is priced the way the app prices a booking today
--   (Money::breakdown with the seeded settings): Rs 42,000 + 10% platform
--   fee + 18% GST on that fee = Rs 46,956; 10% commission, so the creator
--   earns Rs 37,800.
--
-- Timestamps are always consistent with the row's status:
--   requested_at < responded_at = accepted_at < paid_at < started_at
--                < delivered_at < completed_at
--   A pending booking carries none of the later timestamps; delivery_due_at may
--   sit in the future for confirmed / in-progress work, and expires_at is in the
--   future only for still-open requests.
--
-- Idempotent: every INSERT uses ON DUPLICATE KEY UPDATE id = VALUES(id), and the
-- trailing UPDATEs only fill columns that are still NULL. Safe to re-run.
-- =============================================================================

SET NAMES utf8mb4;

-- -----------------------------------------------------------------------------
-- bookings (401-480)
-- -----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `id` = VALUES(`id`);

-- -----------------------------------------------------------------------------
-- booking_offers - live counter-offers plus settled negotiation history
-- -----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `id` = VALUES(`id`);

-- -----------------------------------------------------------------------------
-- booking_deliverables - submissions, approvals and revision requests
-- -----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `id` = VALUES(`id`);

-- -----------------------------------------------------------------------------
-- booking_status_history - ordered transition trail for every booking
-- -----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `id` = VALUES(`id`);

-- -----------------------------------------------------------------------------
-- Guarded links to rows owned by other seed files.
-- These only ever fill columns that are still NULL, and they join on the real
-- data so a booking can never point at a campaign belonging to another brand or
-- at a package belonging to another creator. If those seeds have not been
-- applied yet, the statements simply match nothing.
-- -----------------------------------------------------------------------------
UPDATE `bookings` b
JOIN (
    SELECT `brand_user_id`, MIN(`id`) AS cid
      FROM `campaigns`
     WHERE `id` BETWEEN 301 AND 330
     GROUP BY `brand_user_id`
) c ON c.`brand_user_id` = b.`brand_user_id`
   SET b.`campaign_id` = c.`cid`
 WHERE b.`id` BETWEEN 401 AND 480
   AND b.`campaign_id` IS NULL
   AND (b.`id` % 5) IN (0, 1);

UPDATE `bookings` b
JOIN (
    SELECT `brand_user_id`, MAX(`id`) AS cid
      FROM `campaigns`
     WHERE `id` BETWEEN 301 AND 330
     GROUP BY `brand_user_id`
) c ON c.`brand_user_id` = b.`brand_user_id`
   SET b.`campaign_id` = c.`cid`
 WHERE b.`id` BETWEEN 401 AND 480
   AND b.`campaign_id` IS NULL
   AND (b.`id` % 5) = 2;

UPDATE `bookings` b
JOIN (
    SELECT `creator_id`, MIN(`id`) AS pid
      FROM `creator_packages`
     WHERE `id` BETWEEN 1101 AND 1300
     GROUP BY `creator_id`
) p ON p.`creator_id` = b.`creator_id`
   SET b.`package_id` = p.`pid`
 WHERE b.`id` BETWEEN 401 AND 480
   AND b.`package_id` IS NULL
   AND (b.`id` % 3) = 0;

-- End of 023_demo_bookings.sql
